package com.desktodo.app;
import android.app.*;import android.content.*;import android.content.pm.ActivityInfo;import android.content.res.Configuration;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;
/** Detached native layouts: no activity lifecycle, network, clicks or live product writes. */
public final class UiChecks extends Instrumentation {
 int checks;Throwable failure;
 @Override public void onCreate(Bundle b){start();}
 void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 @Override public void onStart(){runOnMainSync(()->{try{for(float scale:new float[]{1f,1.3f})render(scale);}catch(Throwable e){failure=e;}});Bundle out=new Bundle();out.putString("stream",failure==null?"PASS: "+checks+" detached native layout checks at 360dp / font 1.0 and 1.3; fixture previews exported\n":"FAIL: "+failure+"\n");finish(failure==null?Activity.RESULT_OK:Activity.RESULT_CANCELED,out);}
 void render(float scale)throws Exception{
  Context base=getTargetContext();Configuration configuration=new Configuration(base.getResources().getConfiguration());configuration.fontScale=scale;Context context=base.createConfigurationContext(configuration);ActivityInfo info=new ActivityInfo();info.applicationInfo=base.getApplicationInfo();info.packageName=base.getPackageName();info.name=MainActivity.class.getName();MainActivity a=(MainActivity)newActivity(MainActivity.class,context,null,(Application)base.getApplicationContext(),new Intent(context,MainActivity.class),info,"UI fixture",null,null,null);
  File fixture=new File(base.getCacheDir(),"ui-checks-"+scale+".json");fixture.delete();a.prefs=base.getSharedPreferences("ui-checks",0);a.cfg=DeskModel.defaults();a.tasks=new JSONArray().put(DeskModel.task("整理本周项目进度，与团队确认下一步安排",null)).put(DeskModel.task("下午三点交周报","2026-10-19T07:00:00Z"));a.setup=new SetupPanel(a);a.integrations=new IntegrationPanel(a);a.community=new CommunityPanel(a);a.screen=new ScreenPanel(a);a.assistant=new AssistantPanel(a,new AgentStore(fixture));a.assistant.store.message("user","明天下午三点提醒我交周报");a.assistant.store.message("assistant","已整理为待确认操作，确认后才会加入清单。");AgentTools tools=new AgentTools(new JSONObject().put("tasks",a.tasks).put("settings",a.cfg).put("memories",new JSONArray()),"明天下午三点提醒我交周报");tools.execute("propose_task_change",new JSONObject().put("operation","add").put("title","交周报").put("due","2026-10-19T07:00:00Z"));a.assistant.store.append(tools.proposals);
  try{for(String page:new String[]{"工作台","助手","我的","历史记录","快速收集","每日收尾","连接与数据","桌面方案","布局","信息","设备","偏好记忆","本地提醒","连接设置","选择场景","搭配卡片","重要日期","办公状态","专注计时","习惯打卡","场景收藏","手机日历","通勤建议","共享与扩展","首次配置","自主更新"}){a.page=page;a.draw();measure(a);check(a.statusView.getText().length()>0&&a.statusView.getWidth()>=a.dp(48),"visible status target");check(a.statusView.getRight()<=((View)a.statusView.getParent()).getWidth(),"status inside header: "+a.statusView.getLeft()+","+a.statusView.getRight()+" / "+((View)a.statusView.getParent()).getWidth());check(a.statusView.getLayout()!=null&&a.statusView.getLayout().getHeight()<=a.statusView.getHeight(),"status text fits target");check(a.root.getMeasuredHeight()==a.dp(760),page+" fills viewport");check(a.dock.getBottom()<=a.root.getHeight(),page+" action dock in viewport");targets(a,a.root,page);if(page.equals("助手")){EditText input=a.findViewById(0x00ab1001);check(input!=null&&input.getParent()!=a.body,"composer outside message scroll");check(a.dock.getHeight()>=a.dp(48),"composer usable height");}if(page.equals("布局")){check(a.stagedLayout==null&&a.cfg.optString("layout").equals("overview"),"rendering selection does not mutate config");}if(scale==1f&&(page.equals("工作台")||page.equals("助手")||page.equals("我的")))export(a,page);}
   JSONArray originalHistory=a.history;a.history=new JSONArray().put(new JSONObject().put("id","fixture-history").put("title","Report历史记录").put("recordType","completed").put("completedAt","2026-10-18T03:00:00Z"));String historySnapshot=a.history.toString();a.page="历史记录";a.draw();measure(a);targets(a,a.root,"history-populated");check(a.records.count.getText().toString().contains("1 项"),"history result count");a.records.query="missing";a.records.update();measure(a);check(a.records.results.getChildCount()==1&&a.records.count.getText().toString().contains("0 项"),"empty search result stays in page");check(a.history.toString().equals(historySnapshot),"history UI does not change records");a.history=originalHistory;a.records.query="";
   LinearLayout deadlineForm=new LinearLayout(a);deadlineForm.setOrientation(1);java.util.concurrent.atomic.AtomicReference<java.time.Instant> pickedDeadline=new java.util.concurrent.atomic.AtomicReference<>();DeadlineChoices.controls(a,deadlineForm,pickedDeadline::set);deadlineForm.measure(View.MeasureSpec.makeMeasureSpec(a.dp(320),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(a.dp(500),View.MeasureSpec.AT_MOST));deadlineForm.layout(0,0,deadlineForm.getMeasuredWidth(),deadlineForm.getMeasuredHeight());targets(a,deadlineForm,"deadline-shortcuts");LinearLayout shortcuts=(LinearLayout)deadlineForm.getChildAt(0);java.time.Instant deadlineBefore=java.time.Instant.now();shortcuts.getChildAt(0).performClick();check(pickedDeadline.get().isAfter(deadlineBefore.plusSeconds(3599)),"hour shortcut updates draft");shortcuts.getChildAt(1).performClick();check(pickedDeadline.get().atZone(ScreenData.ZONE).getHour()==9&&pickedDeadline.get().atZone(ScreenData.ZONE).getMinute()==0,"tomorrow shortcut selects nine in Shanghai");
   String captureOriginal=a.tasks.toString();a.capture.draft="UI fixture待确认";a.capture.awaiting=true;a.editing=true;check(!a.capture.drain()&&a.capture.awaiting,"share waits for existing task editor");a.editing=false;a.busy=true;check(!a.capture.drain(),"share waits for current operation");a.busy=false;check(a.capture.drain()&&a.page.equals("快速收集")&&!a.capture.awaiting,"queued share opens preview once");check(a.tasks.toString().equals(captureOriginal),"share preview never writes tasks");a.capture.draft="";
   a.health.receiptOrigin="http://old-device";a.health.lastReceipt=1;check(a.health.receipt()==0,"old device receipt not shown for current address");
   a.page="连接与数据";a.openInfo("天气城市");check(a.page.equals("信息")&&a.infoSection.equals("天气城市"),"health weather action opens actual information page");check(a.backStack.peek()[0].equals("连接与数据"),"health action preserves return destination");a.backStack.clear();
   for(int step=1;step<=4;step++){a.page="首次配置";a.setup.step=step;a.draw();measure(a);targets(a,a.root,"setup-"+step);}
   for(String section:new String[]{"天气城市","自选股票","信息卡片"}){a.page="信息";a.infoSection=section;a.draw();measure(a);targets(a,a.root,section);check(a.location().equals("信息/"+section),"independent page scroll keys");}
  }finally{a.destroyed=true;a.assistant.close();a.worker.shutdownNow();a.ui.removeCallbacksAndMessages(null);fixture.delete();new File(fixture+".bak").delete();base.getSharedPreferences("ui-checks",0).edit().clear().commit();}
 }
 void measure(MainActivity a){a.root.measure(View.MeasureSpec.makeMeasureSpec(a.dp(360),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(a.dp(760),View.MeasureSpec.EXACTLY));a.root.layout(0,0,a.root.getMeasuredWidth(),a.root.getMeasuredHeight());}
 void targets(MainActivity a,View v,String page){if(v.isClickable()&&v.getVisibility()==View.VISIBLE&&!(v instanceof TextView&&((TextView)v).isTextSelectable())){check(v.getWidth()>=a.dp(48)&&v.getHeight()>=a.dp(48),page+" touch target "+v.getClass().getSimpleName()+" "+v.getWidth()+"x"+v.getHeight());}if(v instanceof ViewGroup){ViewGroup group=(ViewGroup)v;for(int n=0;n<group.getChildCount();n++)targets(a,group.getChildAt(n),page);}}
 void export(MainActivity a,String page)throws Exception{Bitmap bitmap=Bitmap.createBitmap(a.root.getWidth(),a.root.getHeight(),Bitmap.Config.ARGB_8888);a.root.draw(new Canvas(bitmap));try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),"ui-preview-"+page+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();}
}
